package typeoracle

func Clone[M interface{ Values() E }, E any](value M) E { return value.Values() }
func CloneMap[M interface{ Mapping() E }, E any](value M) E { return value.Mapping() }
type Holder struct{}; func (Holder) Values() Items { return nil }; func (Holder) Mapping() Lookup { return nil }

type Item struct{ Field int }
func (item *Item) Use(n int) {}
type Other struct{ OtherField int }
func (item *Other) Use(n int) {}
type Items []*Item
type Lookup map[string]*Item
func Navigate(values Holder, lookup Holder) {
 cloned := Clone(values)
 item := cloned[0]
 item.Use(1)
 copied := CloneMap(lookup)
 copied[""].Use(2)
}

